import WorkspaceLayout from '../components/WorkspaceLayout';
import Dialog from '../components/Dialog';
import Skeleton from '../components/Skeleton';
import Badge from '../components/Badge';
import { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Folder, LogOut, Loader2, ChevronRight, Plus, X, Archive, Activity, CheckCircle2, AlertTriangle, Settings, User, Calendar } from 'lucide-react';
import { request } from '../lib/api';

export default function Dashboard() {
    const [projects, setProjects] = useState([]);
    const [activeTab, setActiveTab] = useState('ACTIVE');
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState('');
    const [metrics, setMetrics] = useState({ activeTasks: 0, completedTasks: 0, overdueTasks: 0 });
    const [currentUser, setCurrentUser] = useState(null);
    
    // Create Project Modal States
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [newProjectName, setNewProjectName] = useState('');
    const [isCreating, setIsCreating] = useState(false);

    // Profile Settings Modal States
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [profileData, setProfileData] = useState({ name: '', currentPassword: '', newPassword: '', confirmPassword: '' });
    const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);

    // Interactive Task List Modal States
    const [isTasksModalOpen, setIsTasksModalOpen] = useState(false);
    const [taskModalType, setTaskModalType] = useState('');
    const [modalTasks, setModalTasks] = useState([]);
    const [isLoadingModalTasks, setIsLoadingModalTasks] = useState(false);
    
    const navigate = useNavigate();

    useEffect(() => {
        fetchDashboardData();
    }, []);

    const fetchDashboardData = async () => {
        try {
            setIsLoading(true);
            const [projectsData, metricsData, userData] = await Promise.all([
                request('/projects'),
                request('/tasks/metrics').catch(() => ({ activeTasks: 0, completedTasks: 0, overdueTasks: 0 })),
                request('/users/me').catch(() => null)
            ]);
            setProjects(projectsData);
            setMetrics(metricsData);
            setCurrentUser(userData);
            if (userData) {
                setProfileData({ name: userData.name || '', currentPassword: '', newPassword: '', confirmPassword: '' });
            }
        } catch (err) {
            setError(err.message || 'Failed to load dashboard data.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleMetricClick = async (type) => {
        setTaskModalType(type);
        setIsTasksModalOpen(true);
        setIsLoadingModalTasks(true);
        try {
            const fetchedTasks = await request(`/tasks/${type}`);
            setModalTasks(fetchedTasks);
        } catch (err) {
            alert(err.message || 'Failed to load tasks.');
        } finally {
            setIsLoadingModalTasks(false);
        }
    };

    const handleCreateProject = async (e) => {
        e.preventDefault();
        if (!newProjectName.trim()) return;
        setIsCreating(true);
        try {
            const newProject = await request('/projects', 'POST', { name: newProjectName });
            setProjects([...projects, newProject]);
            setNewProjectName('');
            setIsModalOpen(false);
        } catch (err) {
            alert(err.message || 'Failed to create project.');
        } finally {
            setIsCreating(false);
        }
    };

    const handleUpdateProfile = async (e) => {
        e.preventDefault();
        
        // SECURED: Pre-flight frontend validation
        if (profileData.newPassword) {
            if (profileData.newPassword !== profileData.confirmPassword) {
                alert("New passwords do not match!");
                return;
            }
            if (!profileData.currentPassword) {
                alert("Please enter your current password to authorize this change.");
                return;
            }
        }

        setIsUpdatingProfile(true);
        try {
            const payload = { name: profileData.name };
            if (profileData.newPassword) {
                payload.password = profileData.newPassword;
                payload.currentPassword = profileData.currentPassword;
            }
            
            const updatedUser = await request('/auth/me', 'PUT', payload);
            
            // If password was changed, log them out because their current token was just invalidated
            if (profileData.newPassword) {
                alert('Password updated successfully! For security, please log in again.');
                handleLogout();
                return;
            }

            setCurrentUser(updatedUser);
            setIsProfileModalOpen(false);
            setProfileData({ name: updatedUser.name || '', currentPassword: '', newPassword: '', confirmPassword: '' });
            alert('Profile updated successfully!');
        } catch (err) {
            alert(err.message || 'Failed to update profile.');
        } finally {
            setIsUpdatingProfile(false);
        }
    };

    const handleArchiveProject = async (e, projectId) => {
        e.stopPropagation(); 
        if (!window.confirm("Are you sure you want to archive this project? It will be moved to history.")) return;
        
        try {
            await request(`/projects/${projectId}/archive`, 'PUT');
            setProjects(projects.map(p => p.id === projectId ? { ...p, archived: true } : p));
        } catch (err) {
            alert(err.message || 'Failed to archive project. Only Owners can perform this action.');
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        navigate('/login');
    };

    const displayedProjects = projects.filter(p => activeTab === 'ACTIVE' ? !p.archived : p.archived);

    return (
        <WorkspaceLayout activeTab={activeTab} onTabChange={setActiveTab} onSettings={() => setIsProfileModalOpen(true)} onLogout={handleLogout}>
            <div className="max-w-6xl mx-auto">
                <div className="flex flex-col items-start justify-between mb-8 sm:flex-row sm:items-center gap-4">
                    <div>
                        <p className="eyebrow mb-3">Your workspace, at a glance</p>
                        <h1 className="text-3xl font-bold tracking-tight text-ink">
                            Welcome, {currentUser?.name || 'User'}
                        </h1>
                        <p className="mt-1 text-sm text-muted">Manage your active projects and teams</p>
                    </div>
                    <div className="flex items-center space-x-3">
                        <button onClick={() => setIsModalOpen(true)} className="flex items-center px-4 py-2.5 text-sm font-semibold text-white transition-all shadow-sm bg-brand-600 rounded-xl hover:bg-brand-700">
                            <Plus className="w-4 h-4 mr-2" /> New Project
                        </button>
                        <button aria-label="Profile Settings" onClick={() => setIsProfileModalOpen(true)} title="Profile Settings" className="flex items-center px-4 py-2.5 text-sm font-medium transition-colors bg-panel border shadow-sm rounded-xl text-muted border-line hover:bg-elevated">
                            <Settings className="w-4 h-4" />
                        </button>
                        <button aria-label="Log Out" onClick={handleLogout} title="Log Out" className="flex items-center px-4 py-2.5 text-sm font-medium transition-colors bg-panel border shadow-sm rounded-xl text-muted border-line hover:bg-elevated">
                            <LogOut className="w-4 h-4" />
                        </button>
                    </div>
                </div>

                <div className="metric-grid grid grid-cols-1 xl:grid-cols-3 gap-4 mb-10">
                    <button onClick={() => handleMetricClick('active')} className="flex items-center p-6 text-left transition-all bg-panel border cursor-pointer border-line rounded-2xl shadow-sm hover:shadow-md hover:border-brand-200 group">
                        <div className="p-3 mr-4 transition-colors bg-brand-50 rounded-xl group-hover:bg-brand-100">
                            <Activity className="w-6 h-6 text-brand-600" />
                        </div>
                        <div>
                            <p className="text-sm font-medium text-muted group-hover:text-brand-600 transition-colors">Active Tasks</p>
                            <h3 className="text-2xl font-bold text-ink">{isLoading ? <span className="skeleton-line inline-block w-12 mb-0" aria-label="Loading count" /> : metrics.activeTasks}</h3>
                        </div>
                    </button>
                    
                    <button onClick={() => handleMetricClick('completed')} className="flex items-center p-6 text-left transition-all bg-panel border cursor-pointer border-line rounded-2xl shadow-sm hover:shadow-md hover:border-emerald-200 group">
                        <div className="p-3 mr-4 transition-colors bg-emerald-50 rounded-xl group-hover:bg-emerald-100">
                            <CheckCircle2 className="w-6 h-6 text-emerald-600" />
                        </div>
                        <div>
                            <p className="text-sm font-medium text-muted group-hover:text-emerald-600 transition-colors">Completed</p>
                            <h3 className="text-2xl font-bold text-ink">{isLoading ? <span className="skeleton-line inline-block w-12 mb-0" aria-label="Loading count" /> : metrics.completedTasks}</h3>
                        </div>
                    </button>

                    <button onClick={() => handleMetricClick('overdue')} className="flex items-center p-6 text-left transition-all bg-panel border cursor-pointer border-line rounded-2xl shadow-sm hover:shadow-md hover:border-red-200 group">
                        <div className="p-3 mr-4 transition-colors bg-red-50 rounded-xl group-hover:bg-red-100">
                            <AlertTriangle className="w-6 h-6 text-red-600" />
                        </div>
                        <div>
                            <p className="text-sm font-medium text-muted group-hover:text-red-600 transition-colors">Overdue Tasks</p>
                            <h3 className="text-2xl font-bold text-ink">{isLoading ? <span className="skeleton-line inline-block w-12 mb-0" aria-label="Loading count" /> : metrics.overdueTasks}</h3>
                        </div>
                    </button>
                </div>

                <h2 className="text-xl font-semibold mb-5">Projects</h2>
                <div className="flex space-x-6 border-b border-line mb-8" role="group" aria-label="Project view">
                    <button aria-pressed={activeTab === 'ACTIVE'} onClick={() => setActiveTab('ACTIVE')} className={`pb-3 text-sm font-medium transition-colors border-b-2 ${activeTab === 'ACTIVE' ? 'border-brand-600 text-brand-700' : 'border-transparent text-muted hover:text-muted'}`}>
                        Active Projects
                    </button>
                    <button aria-pressed={activeTab === 'ARCHIVED'} onClick={() => setActiveTab('ARCHIVED')} className={`pb-3 text-sm font-medium transition-colors border-b-2 ${activeTab === 'ARCHIVED' ? 'border-brand-600 text-brand-700' : 'border-transparent text-muted hover:text-muted'}`}>
                        Archived Projects
                    </button>
                </div>

                {error && <div role="alert" className="notice"><AlertTriangle size={20} /><span>Unable to load your workspace. Please refresh to try again.</span></div>}
                {isLoading ? (
                    <Skeleton />
                ) : (
                    <div className="grid grid-cols-1 gap-5 md:grid-cols-2 lg:grid-cols-3">
                        {displayedProjects.map((project) => (
                            <div key={project.id} className="project-card group flex flex-col p-6 bg-panel border border-line rounded-2xl">
                                <div className="flex items-center justify-between mb-5">
                                    <div className="flex items-center justify-center w-12 h-12 rounded-xl bg-elevated group-hover:bg-brand-50 transition-colors">
                                        <Folder className="w-6 h-6 text-subtle group-hover:text-brand-600" />
                                    </div>
                                    <div className="flex space-x-2">
                                        {!project.archived && (
                                            <button aria-label="Archive Project" onClick={(e) => handleArchiveProject(e, project.id)} className="p-2 transition-all  rounded-full bg-elevated hover:bg-red-50 text-subtle hover:text-red-600 group-hover:opacity-100 group-hover:scale-100" title="Archive Project">
                                                <Archive className="w-4 h-4" />
                                            </button>
                                        )}
                                        <div className="flex items-center justify-center w-8 h-8 transition-all  rounded-full bg-elevated group-hover:opacity-100 group-hover:scale-100">
                                            <ChevronRight className="w-4 h-4 text-brand-600" />
                                        </div>
                                    </div>
                                </div>
                                <h3 className="text-lg font-semibold text-ink"><Link className="project-link" to={`/projects/${project.id}`}>{project.name}</Link></h3>
                                <p className="mt-1 text-sm text-muted line-clamp-2">
                                    {project.archived ? 'Archived project (Read-only)' : 'Click to view tasks and manage team members'}
                                </p>
                            </div>
                        ))}
                        
                        {displayedProjects.length === 0 && !error && (
                            <div className="col-span-full py-16 text-center border-2 border-dashed rounded-2xl border-line bg-panel/50">
                                <p className="text-sm text-muted">
                                    {activeTab === 'ACTIVE' ? 'No active projects. Create one to get started.' : 'No archived projects in history.'}
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {isTasksModalOpen && (
                <Dialog label={`${taskModalType} tasks`} labelledBy="metric-dialog-title" onClose={() => setIsTasksModalOpen(false)} wide>
                    <div className="w-full max-w-2xl p-6 bg-panel shadow-xl flex flex-col rounded-3xl animate-in zoom-in-95 max-h-[85vh]">
                        <div className="flex items-center justify-between mb-6 shrink-0">
                            <h2 id="metric-dialog-title" className="text-xl font-bold capitalize text-ink">
                                {taskModalType} Tasks
                            </h2>
                            <button aria-label="Close dialog" onClick={() => setIsTasksModalOpen(false)} className="p-2 transition-colors rounded-full text-subtle hover:bg-elevated">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        
                        <div className="overflow-y-auto pr-2 flex-grow scrollbar-thin">
                            {isLoadingModalTasks ? (
                                <div className="flex items-center justify-center py-12"><Loader2 role="status" aria-label="Loading" className="w-8 h-8 animate-spin text-brand-600" /></div>
                            ) : modalTasks.length === 0 ? (
                                <div className="py-12 text-center">
                                    <p className="text-muted">No {taskModalType} tasks found.</p>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {modalTasks.map(task => (
                                        <div 
                                            key={task.id} 
                                            role="link" tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter") navigate(`/projects/${task.projectId}`); }} onClick={() => navigate(`/projects/${task.projectId}`)}
                                            className="task-row rounded-xl cursor-pointer group"
                                        >
                                            <div className="pr-4">
                                                <h4 className="font-semibold text-ink group-hover:text-brand-600 transition-colors">{task.title}</h4>
                                                <div className="task-meta">
                                                    <Badge value={task.priority || "NORMAL"} priority />
                                                    <Badge value={task.status} />
                                                </div>
                                            </div>
                                            
                                            <div className="flex flex-col items-end shrink-0">
                                                {task.deadline && (
                                                    <div className={`flex items-center text-sm ${
                                                        taskModalType === 'overdue' ? 'text-red-600 font-medium' : 'text-muted'
                                                    }`}>
                                                        <Calendar className="w-4 h-4 mr-1.5" />
                                                        {new Date(task.deadline).toLocaleDateString()}
                                                    </div>
                                                )}
                                                <span className="flex items-center mt-2 text-xs font-medium text-brand-600  transition-opacity">
                                                    Go to project <ChevronRight className="w-3 h-3 ml-1" />
                                                </span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </Dialog>
            )}

            {isModalOpen && (
                <Dialog label="Create New Project" labelledBy="create-project-title" onClose={() => setIsModalOpen(false)}>
                    <div className="w-full max-w-md p-6 bg-panel shadow-xl rounded-3xl animate-in zoom-in-95">
                        <div className="flex items-center justify-between mb-6">
                            <h2 id="create-project-title" className="text-xl font-bold text-ink">Create New Project</h2>
                            <button aria-label="Close dialog" onClick={() => setIsModalOpen(false)} className="p-2 transition-colors rounded-full text-subtle hover:bg-elevated">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <form onSubmit={handleCreateProject}>
                            <div className="mb-8">
                                <label htmlFor="dashboard-field-1" className="block mb-2 text-sm font-medium text-muted">Project Name</label>
                                <input id="dashboard-field-1"
                                    type="text"
                                    required
                                    data-autofocus="true"
                                    value={newProjectName}
                                    onChange={(e) => setNewProjectName(e.target.value)}
                                    className="w-full px-4 py-3 text-sm transition-colors border rounded-xl border-line focus:outline-none focus:ring-2 focus:ring-brand-500"
                                    placeholder="e.g., Q3 Marketing Campaign"
                                />
                            </div>
                            <button aria-live="polite" type="submit" disabled={isCreating} className="w-full flex items-center justify-center py-3 text-sm font-semibold text-white transition-colors bg-brand-600 rounded-xl hover:bg-brand-700 disabled:opacity-70">
                                {isCreating ? <Loader2 role="status" aria-label="Loading" className="w-5 h-5 animate-spin" /> : 'Create Project'}
                            </button>
                        </form>
                    </div>
                </Dialog>
            )}

            {isProfileModalOpen && (
                <Dialog label="Account Settings" labelledBy="account-settings-title" onClose={() => setIsProfileModalOpen(false)}>
                    <div className="w-full max-w-md p-6 bg-panel shadow-xl rounded-3xl animate-in zoom-in-95">
                        <div className="flex items-center justify-between mb-6">
                            <h2 id="account-settings-title" className="text-xl font-bold text-ink">Account Settings</h2>
                            <button aria-label="Close dialog" onClick={() => setIsProfileModalOpen(false)} className="p-2 transition-colors rounded-full text-subtle hover:bg-elevated">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        
                        <div className="flex items-center mb-6 space-x-4 p-4 bg-elevated rounded-xl border border-line">
                            <div className="p-3 bg-panel rounded-full shadow-sm">
                                <User className="w-6 h-6 text-brand-600" />
                            </div>
                            <div>
                                <p className="text-sm font-medium text-ink">{currentUser?.email}</p>
                                <p className="text-xs text-muted">Role: {currentUser?.role}</p>
                            </div>
                        </div>

                        <form onSubmit={handleUpdateProfile}>
                            <div className="mb-4">
                                <label htmlFor="dashboard-field-2" className="block mb-2 text-sm font-medium text-muted">Display Name</label>
                                <input id="dashboard-field-2"
                                    type="text"
                                    required
                                    value={profileData.name}
                                    onChange={(e) => setProfileData({...profileData, name: e.target.value})}
                                    className="w-full px-4 py-3 text-sm transition-colors border rounded-xl border-line focus:outline-none focus:ring-2 focus:ring-brand-500"
                                />
                            </div>
                            
                            <div className="mb-4 border-t pt-4 border-line">
                                <label htmlFor="dashboard-field-3" className="block mb-2 text-sm font-medium text-muted">
                                    New Password <span className="font-normal text-subtle">(leave blank to keep current)</span>
                                </label>
                                <input id="dashboard-field-3"
                                    type="password"
                                    value={profileData.newPassword}
                                    onChange={(e) => setProfileData({...profileData, newPassword: e.target.value})}
                                    className="w-full px-4 py-3 text-sm transition-colors border rounded-xl border-line focus:outline-none focus:ring-2 focus:ring-brand-500"
                                    placeholder="Enter new password"
                                    minLength={6}
                                />
